const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]).buffer(20000); // 20km radius around Wuhan
  const period1Start = '2020-01-01';
  const period1End = '2020-01-20';
  const period2Start = '2020-02-10';
  const period2End = '2020-02-25';

  // 2. Data Acquisition
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/NOFDI/L3_NO2')
    .select('NO2_column_number_density');

  // Filter for period 1
  const period1 = no2Collection
    .filterDate(period1Start, period1End)
    .filterBounds(wuhan);

  // Filter for period 2
  const period2 = no2Collection
    .filterDate(period2Start, period2End)
    .filterBounds(wuhan);

  const size1 = await period1.size().getInfo();
  const size2 = await period2.size().getInfo();

  console.log(`Period 1 (Jan 1-20) Images: ${size1}`);
  console.log(`Period 2 (Feb 10-25) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Insufficient data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Quality masking and mean calculation
  function maskQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  const period1Masked = period1.map(maskQuality).mean();
  const period2Masked = period2.map(maskQuality).mean();

  // 4. Calculate statistics
  const stats1 = await period1Masked.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await period2Masked.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.NO2_column_number_density_mean;
  const count1 = stats1.NO2_column_number_density_count;
  const mean2 = stats2.NO2_column_number_density_mean;
  const count2 = stats2.NO2_column_number_density_count;

  console.log(`Period 1: Mean NO2 = ${mean1}, Valid Pixels = ${count1}`);
  console.log(`Period 2: Mean NO2 = ${mean2}, Valid Pixels = ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 === null || mean1 === undefined || mean2 === null || mean2 === undefined ||
      isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation failed: invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  const decrease = mean2 < mean1;
  const percentChange = ((mean2 - mean1) / mean1 * 100).toFixed(2);

  console.log(`Percent change: ${percentChange}%`);

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
